<?php use Simit\Core\{Auth,Csrf}; ?>
<div class="toolbar"><div><h2><?=__('Akun internal','Internal accounts')?></h2><p class="muted"><?=__('Hanya admin yang dapat mendaftarkan dan mengelola akun.','Only administrators can register and manage accounts.')?></p></div><a class="btn primary" href="/akun/create">+ <?=__('Daftarkan akun','Register account')?></a></div>
<div class="panel table-panel"><div class="table-wrap"><table><thead><tr><th><?=__('Pengguna','User')?></th><th>Email</th><th><?=__('Peran','Role')?></th><th>Status</th><th><?=__('Dibuat','Created')?></th><th class="actions"><?=__('Aksi','Actions')?></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><?php if((int)$r['id']===(int)Auth::user()['id']):?><small><?=__('Akun Anda','Your account')?></small><?php endif;?></td><td><?=e($r['email'])?></td><td><span class="badge"><?=e(ucfirst($r['role']))?></span></td><td><span class="badge <?=$r['is_active']?'':'danger'?>"><?=$r['is_active']?__('Aktif','Active'):__('Nonaktif','Inactive')?></span></td><td><?=e(substr($r['created_at'],0,10))?></td><td class="actions"><a class="icon-action" href="/akun/edit/<?=$r['id']?>">✎</a><?php if((int)$r['id']!==(int)Auth::user()['id']):?><form method="post" action="/akun/toggle/<?=$r['id']?>"><?=Csrf::field()?><button class="link-btn"><?=$r['is_active']?__('Nonaktifkan','Deactivate'):__('Aktifkan','Activate')?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
